package net.officefloor.hq.app.grade;

import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Refuses a merge by anyone but a steward, on an archived sheet, of a grade into itself, of a grade
 *  not one of the sheet's, or into a retired grade. */
public class ValidateGradeMerge {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody GradeMergeRequest request,
            Settings settings, Sheets sheets, Grades grades, Out<GradeMerge> merge)
            throws InvalidSheetRequestException {
        if (request == null || request.user() == null || settings.role(sheetId, request.user()) != Role.STEWARD) {
            throw new InvalidSheetRequestException("Only a steward can merge grades");
        }
        if (sheets.archived(sheetId)) {
            throw new InvalidSheetRequestException("The sheet is archived");
        }
        String from = request.from() == null ? "" : request.from().trim();
        String into = request.into() == null ? "" : request.into().trim();
        if (!Grades.ALL.contains(from) || !Grades.ALL.contains(into)) {
            throw new InvalidSheetRequestException("The grades must be A, B or C");
        }
        if (from.equals(into)) {
            throw new InvalidSheetRequestException("A grade cannot be merged into itself");
        }
        grades.refuseRetired(sheetId, into);
        merge.set(new GradeMerge(sheetId, from, into, request.user()));
    }
}
=== ValidateRetireGrade.java
package net.officefloor.hq.app.grade;

import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Refuses a grade that is not one of the sheet's, or one already retired. */
public class ValidateRetireGrade {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody GradeRequest request, Grades grades,
            Out<GradeRetirement> retirement, Out<Actor> actor) throws InvalidSheetRequestException {
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        if (!Grades.ALL.contains(grade)) {
            throw new InvalidSheetRequestException("The grade must be A, B or C");
        }
        if (grades.isRetired(sheetId, grade)) {
            throw new InvalidSheetRequestException("The grade " + grade + " is already retired");
        }
        retirement.set(new GradeRetirement(sheetId, grade, request.user()));
        actor.set(new Actor(request.user()));
    }
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { gradesKey, useGrades, type Grade } from './useGrades';

/**
 * The sheet's grades, each shown retired or not, and a select to retire one. A retired grade cannot
 * be chosen for a person any more (the people already on it keep it); retiring one twice is refused.
 * A steward can merge a grade into another: everyone on it today is given the other from the sheet's
 * today. The merge shows the grades and how many it moved; that goes while the next press runs.
 */
function GradesPanel({ user, sheet }: { user: string; sheet: string }) {
  const queryClient = useQueryClient();
  const { data: grades = [] } = useGrades(sheet);
  const [grade, setGrade] = useState('A');
  const [mergeFrom, setMergeFrom] = useState('A');
  const [mergeInto, setMergeInto] = useState('B');

  const submitOnce = useSubmitOnce();
  const retire = useMutation({
    mutationFn: (g: string) => postJson<Grade[]>(`/api/sheets/${encodeURIComponent(sheet)}/grades/retire`, { grade: g, user }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: gradesKey(sheet) });
    },
  });

  const merge = useMutation({
    mutationFn: (m: { from: string; into: string }) =>
      postJson<{ from: string; into: string; moved: number }>(
        `/api/sheets/${encodeURIComponent(sheet)}/grades/merge`,
        { ...m, user },
      ),
    // Everyone moved changes the people, their claims' figures and the sheet's totals.
    onSettled: () => queryClient.invalidateQueries({ queryKey: ['sheet', sheet] }),
  });

  return (
    <section data-testid="grades-panel">
      <h2>Grades</h2>
      <form
        data-testid="grade-retire-form"
        onSubmit={(e) => {
          e.preventDefault();
          retire.reset();
          merge.reset();
          submitOnce(() => retire.mutateAsync(grade));
        }}
      >
        <label>
          Grade{' '}
          <select
            data-testid="grade-retire-select"
            value={grade}
            onChange={(e) => {
              setGrade(e.target.value);
              retire.reset();
            }}
          >
            {grades.map((g) => (
              <option key={g.grade} value={g.grade}>
                {g.grade}
              </option>
            ))}
          </select>
        </label>{' '}
        <button type="submit" data-testid="grade-retire" disabled={retire.isPending}>
          Retire grade
        </button>
        {retire.isError && (
          <span data-testid="grade-error" role="alert">
            {' '}
            Could not retire this grade.
          </span>
        )}
      </form>
      <form
        data-testid="grade-merge-form"
        onSubmit={(e) => {
          e.preventDefault();
          retire.reset();
          merge.reset();
          submitOnce(() => merge.mutateAsync({ from: mergeFrom, into: mergeInto }));
        }}
      >
        <label>
          Merge{' '}
          <select
            data-testid="grade-merge-from"
            value={mergeFrom}
            onChange={(e) => {
              setMergeFrom(e.target.value);
              merge.reset();
            }}
          >
            {grades.map((g) => (
              <option key={g.grade} value={g.grade}>
                {g.grade}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          into{' '}
          <select
            data-testid="grade-merge-into"
            value={mergeInto}
            onChange={(e) => {
              setMergeInto(e.target.value);
              merge.reset();
            }}
          >
            {grades.map((g) => (
              <option key={g.grade} value={g.grade}>
                {g.grade}
              </option>
            ))}
          </select>
        </label>{' '}
        <button type="submit" data-testid="grade-merge" disabled={merge.isPending}>
          Merge grade
        </button>
        {merge.isSuccess && (
          <span>
            {' '}
            Moved <strong data-testid="grade-merged">{`${merge.data.from} into ${merge.data.into}: ${merge.data.moved}`}</strong>
          </span>
        )}
        {merge.isError && (
          <span data-testid="grade-error" role="alert">
            {' '}
            Could not merge these grades.
          </span>
        )}
      </form>
      <table data-testid="grade-list">
        <tbody>
          {grades.map((g) => (
            <tr key={g.grade} data-testid={`grade-row-${g.grade}`}>
              <td data-testid="grade-code">{g.grade}</td>
              <td data-testid="grade-retired">{g.retired ? 'yes' : 'no'}</td>
