import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A grade as the server sends it: its code and whether it is retired. */
export type Grade = { grade: string; retired: boolean };

export const gradesKey = (sheet: string) => ['sheet', sheet, 'grades'] as const;

/** The sheet's grades, in order, re-read whenever the sheet is loaded. */
export function useGrades(sheet: string) {
  return useQuery({
    queryKey: gradesKey(sheet),
    queryFn: () => getJson<Grade[]>(`/api/sheets/${encodeURIComponent(sheet)}/grades`),
    staleTime: 0,
    gcTime: 0,
  });
}
  return retiredOut(person, today);
}

/** By person id, whether a claim dated then is held out (see `heldOn`) on the sheet's `today`. */
export function heldOnBy(people: Person[], today: string): (personId: number, date: string) => boolean {
  const byId = new Map(people.map((p) => [p.id, p]));
  return (personId, date) => {
    const p = byId.get(personId);
    return p !== undefined && heldOn(p, date, today);
  };
}

export const GRADES = ['A', 'B', 'C'] as const;

export const peopleKey = (sheet: string) => ['sheet', sheet, 'people'] as const;

/** The sheet's people in list order (by position; see the move buttons), re-read whenever the sheet is loaded. */
export function usePeople(sheet: string) {
  const view = useView();
  return useQuery({
    queryKey: viewKey(peopleKey(sheet), view),
    queryFn: () => getJson<Person[]>(viewPath(`/api/sheets/${encodeURIComponent(sheet)}/people`, view)),
    staleTime: 0,
    gcTime: 0,
  });
}
import { useSheetTotals } from '../claims/useSheetTotals';
import { GRADES, gradeOn } from '../people/usePeople';
import { useSheetToday } from '../sheet/useSheet';

/**
 * Per grade, the people not retired on it on the sheet's today, each with their due-total in cents
 * (null when n/a), worked out as the list works it out (their parts of the claims shared with them
 * included, see useSheetTotals). One place, so the summary and the consolidated figures agree.
 */
export function useGradeDues(sheet: string) {
  const { perPerson } = useSheetTotals(sheet);
  const today = useSheetToday(sheet);
  const people = perPerson.filter((d) => !d.person.retired);
  return Object.fromEntries(
    GRADES.map((g) => [g, people.filter((d) => gradeOn(d.person, today) === g).map(({ person, due }) => ({ person, due }))]),
  ) as Record<(typeof GRADES)[number], Array<{ person: (typeof people)[number]['person']; due: bigint | null }>>;
}
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { isActive } from '../active/active';
import { STATUSES, useClaims } from '../claims/useClaims';
import { GRADES, usePeople } from '../people/usePeople';
import { periodDue, usePeriods } from '../periods/usePeriods';
import { hundredths, totalDue, useRates } from '../rates/useRates';
import { useFloor, useLate, useReviewLate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheet';
import { useVoidReasons } from '../voidreasons/useVoidReasons';
import { useGradeDues } from './useGradeDues';

/**
 * The sheet in figures, each worked out as the list works it out. Per grade: how many people not
 * retired are on it on the sheet's today, their due-totals added up (n/a ones skipped), and how many
 * of them are active. Per
 * period: its due-total, and its change from the period before it by from-date (none for the
 * earliest). Per status: how many of the sheet's claims have it, and how many REVIEW claims are review-late. Per void reason on
 * the sheet's list: how many VOID claims were voided with it.
 */
function SummaryPanel({ sheet }: { user: string; sheet: string }) {
  const { data: all = [] } = useClaims(sheet);
  const { data: everyone = [] } = usePeople(sheet);
  const { data: periods = [] } = usePeriods(sheet);
  const { data: rates = [] } = useRates(sheet);
  const { data: voidReasons = [] } = useVoidReasons(sheet);
  const today = useSheetToday(sheet);
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  const reviewLate = useReviewLate(sheet);
  const byGrade = useGradeDues(sheet);

  const periodDues = new Map(periods.map((p) => [p.name, periodDue(p, all, everyone, rates, floor, late, today)]));
  const byFrom = [...periods].sort((a, b) => (a.from < b.from ? -1 : a.from > b.from ? 1 : 0));
  const changeOf = (p: (typeof periods)[number]) => {
    const i = byFrom.indexOf(p);
    if (i <= 0) return '';
    return totalDue([hundredths(periodDues.get(p.name)!) - hundredths(periodDues.get(byFrom[i - 1].name)!)]);
  };

  return (
    <section data-testid="summary-panel">
      <h2>Summary</h2>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due</th>
            <th>Active</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const on = byGrade[g];
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{on.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}>{totalDue(on.map((d) => d.due))}</td>
                <td data-testid={`summary-grade-${g}-active`}>{on.filter((d) => isActive(d.person, all, today)).length}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due</th>
            <th>Change</th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}>{periodDues.get(p.name)}</td>
              <td data-testid={`summary-period-${p.name}-change`}>{changeOf(p)}</td>
            </tr>
          ))}
        </tbody>
