          submitOnce(() => add.mutateAsync(code));
        }}
      >
        <label>
          New grade{' '}
          <input
            data-testid="grade-add-code"
            placeholder="D"
            value={code}
            onChange={(e) => {
              setCode(e.target.value);
              add.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="grade-add" disabled={add.isPending}>
          Add grade
        </button>
        {add.isError && (
          <span data-testid="grade-error" role="alert">
            {' '}
            Could not add this grade.
          </span>
        )}
      </form>
""")
s=s.replace("""          e.preventDefault();
          retire.reset();
          merge.reset();""","""          e.preventDefault();
          resetAll();""")
open(p,'w').write(s)
